var NLB={"1": {"prof": ["Presoaking dei trapianti in vancomicina nel LCA: evidenza osservazionale, diretta solo per gli ischiocrurali", "Revisione State of the Art (J ISAKOS, 2026; narrativa, solo abstract). Coorti comparative ampie e analisi aggregate associano il presoaking in vancomicina a meno artrite settica dopo LCA; l'evidenza più diretta riguarda gli ischiocrurali, i pochi RCT sono sottodimensionati per un evento raro e per quadricipite, rotuleo e allotrapianto i dati sono limitati o indiretti.", "Nota critica: nessun dato aggregato nell'abstract; una serie 2026 non controllata sul quadricipite segnala un possibile problema di sicurezza, non confermato e non definito come controindicazione; il presoaking non sostituisce la profilassi sistemica."], "mix": ["Crociato: bagnare il trapianto in vancomicina prima dell'impianto, che cosa dicono gli studi", "Un'infezione dell'articolazione dopo la ricostruzione del legamento crociato è rara ma può essere grave. Una revisione recente riassume gli studi sul bagno del tendine in un antibiotico prima di impiantarlo: la maggior parte è osservazionale e associa il bagno a meno infezioni, con i dati più diretti per il tendine preso dalla parte posteriore della coscia.", "Nota sul limite: per altri tipi di tendine, compreso il quadricipite, i dati sono pochi, e una serie non controllata segnala un possibile problema di sicurezza che non è stato confermato; il bagno si aggiunge alle altre misure di prevenzione, non le sostituisce."], "paz": ["Legamento crociato: cosa si sa del bagno del tendine in antibiotico prima dell'operazione", "In alcune operazioni al legamento crociato il tendine viene tenuto per qualche minuto in un antibiotico prima di essere posizionato, per ridurre il rischio di infezione, che è rara. Una revisione degli studi osserva che chi lo ha ricevuto ha avuto meno infezioni, soprattutto con il tendine preso dalla parte posteriore della coscia.", "Nota rassicurante: è una misura in più, che si affianca alla profilassi abituale; per altri tipi di tendine i dati sono ancora pochi, e la scelta spetta al chirurgo caso per caso."], "kw": "legamento crociato, infezione dopo il crociato, vancomicina, ricostruzione del crociato, prevenzione delle infezioni"}, "2": {"prof": ["LCA con ischiocrurali e Lemaire modificato nell'iperlassità generalizzata: serie di 25 pazienti, 2 anni", "Serie retrospettiva a braccio singolo (BMC Musculoskelet Disord, 2026; livello IV, solo abstract): 25 pazienti con iperlassità generalizzata, follow-up medio 25,76 ± 1,42 mesi. Differenza laterale al KT-1000 da 11,77 ± 1,80 a 1,68 ± 1,25 mm (p < 0,001); Lysholm da 55,48 ± 19,62 a 91,32 ± 4,89; pivot-shift di grado I residuo in 5 pazienti.", "Nota critica: nessun confronto con la sola ricostruzione, innesto di ischiocrurali, follow-up troppo breve per le rotture; dice che i punteggi migliorano, non che il LET sia la causa."], "mix": ["Crociato e articolazioni molto elastiche: uno studio su 25 pazienti operati con un rinforzo laterale", "In persone con articolazioni molto elastiche (iperlassità generalizzata) la ricostruzione del crociato fallisce più spesso. Uno studio cinese ha seguito per circa due anni 25 pazienti operati con tendini della coscia più un rinforzo laterale esterno all'articolazione: la lassità misurata con lo strumento è scesa da circa 12 a circa 2 millimetri e i punteggi funzionali sono saliti.", "Nota sul limite: mancava un gruppo operato senza rinforzo, quindi non si può dire quanto del miglioramento dipenda dal rinforzo; il periodo di controllo è breve per giudicare le rotture."], "paz": ["Crociato operato con articolazioni molto elastiche: cosa mostra uno studio su 25 persone", "Chi ha articolazioni molto elastiche ha un rischio maggiore che il legamento ricostruito ceda di nuovo. In uno studio su 25 persone operate con un rinforzo aggiuntivo sul lato esterno del ginocchio, dopo circa due anni il ginocchio risultava più stabile alle misure e i punteggi di funzione erano migliorati.", "Nota rassicurante: lo studio è piccolo e senza gruppo di confronto, quindi non dimostra che il rinforzo serva a tutti; la scelta dell'intervento dipende dal singolo caso e dal parere del chirurgo."], "kw": "legamento crociato, iperlassità, articolazioni elastiche, tenodesi laterale, instabilità del ginocchio"}, "3": {"prof": ["Menisco nel LCA dell'atleta professionista: revisione sistematica di 5 studi, 519 pazienti", "Revisione sistematica PRISMA (Ann Jt, 2026; studi retrospettivi, solo abstract): lesioni meniscali nel 59-86% degli atleti, riparazione favorita nelle lesioni riparabili. Le lesioni mediali falliscono e finiscono in meniscectomia più delle laterali, soprattutto con tecnica all-inside; inside-out e suture hook appaiono più favorevoli sul lato mediale.", "Nota critica: 5 studi retrospettivi eterogenei, atleti professionisti (età media 23,7 anni), nessun tasso di fallimento per tecnica nell'abstract; il ritorno allo sport senza intervalli di confidenza."], "mix": ["Crociato negli atleti professionisti: il menisco danneggiato si ripara quando è possibile", "In cinque studi su 519 atleti professionisti operati di crociato, il menisco era danneggiato in una percentuale compresa fra il 59% e l'86% dei casi. Quando la lesione si può riparare si preferisce ripararla, e la riparazione non sembra ostacolare il ritorno allo sport; sul lato interno del ginocchio le riparazioni con alcune tecniche hanno ceduto più spesso.", "Nota sul limite: sono pochi studi, non confrontati fra loro con numeri precisi, su atleti d'élite; non si applicano automaticamente a ogni persona."], "paz": ["Crociato e menisco: negli sportivi si cerca di riparare il menisco invece di toglierlo", "Quando il legamento crociato si lesiona, spesso si danneggia anche il menisco, la struttura che fa da cuscinetto nel ginocchio. Negli sportivi professionisti, gli studi esaminati indicano che, se possibile, il menisco viene riparato e non asportato, senza che questo sembri impedire di tornare a giocare.", "Nota rassicurante: la scelta fra riparare e togliere dipende dal tipo di lesione e dal singolo caso, e viene definita con il chirurgo."], "kw": "menisco, legamento crociato, riparazione del menisco, sportivi, ritorno allo sport"}, "4": {"prof": ["Osteotomie di riduzione dello slope nel fallimento del LCA: revisione narrativa, nessun RCT", "Revisione narrativa (Ann Jt, 2026; solo abstract). Le osteotomie anteriori sovra-, infra- e trans-tuberositarie mostrano esiti incoraggianti nei fallimenti dell'innesto con slope tibiale elevato; l'evidenza è retrospettiva e tecnica, senza RCT comparativi, e viene proposto un algoritmo di indicazioni.", "Nota critica: nessun dato aggregato nell'abstract, misura dello slope non standardizzata, guide paziente-specifiche poco documentate; scelta della tecnica legata ad anatomia ed esperienza."], "mix": ["Crociato che cede ancora: correggere la pendenza del piatto tibiale, che cosa dice la letteratura", "Se il legamento ricostruito si rompe di nuovo e la superficie superiore della tibia è molto inclinata all'indietro, si può correggere l'inclinazione con un'osteotomia, cioè un taglio dell'osso. Una revisione descrive quattro approcci e riporta esiti incoraggianti per tre di quelli anteriori.", "Nota sul limite: si basa su studi retrospettivi e descrizioni tecniche, senza confronti diretti fra le tecniche; non permette di dire quale sia preferibile."], "paz": ["Legamento crociato rotto di nuovo: la pendenza della tibia può essere corretta con un'osteotomia", "In alcuni ginocchi la parte alta della tibia è molto inclinata all'indietro, e questo può sovraccaricare il legamento ricostruito. Una revisione della letteratura descrive diversi modi di correggere l'inclinazione con un piccolo taglio dell'osso, con risultati incoraggianti nei casi studiati.", "Nota rassicurante: è un intervento riservato a casi selezionati e le prove sono ancora limitate; il chirurgo valuta caso per caso se sia indicato."], "kw": "legamento crociato, revisione del crociato, osteotomia, pendenza della tibia, ginocchio"}, "5": {"prof": ["Segnalazioni MAUDE sui robot in artroplastica: etichette di danno e codici paziente non coincidono", "Analisi trasversale (J Robot Surg, 2026; livello basso, solo abstract) di 12.175 segnalazioni MAUDE su Mako, NAVIO/CORI, VELYS e ROSA: etichetta «lesione» nel 17,3%, dallo 0,6% (VELYS) al 44,2% (ROSA); co-occorrenza di etichetta e codici del paziente discordanti in 1.785 (14,7%; IC 95% 14,0-15,3).", "Nota critica: sorveglianza passiva senza denominatore di interventi; l'autore stesso esclude che le percentuali misurino la sicurezza o servano a ordinare le piattaforme."], "mix": ["Protesi di ginocchio robotica: perché le segnalazioni di eventi non misurano la sicurezza dei sistemi", "In un database pubblico americano di segnalazioni su sistemi robotici per protesi (12.175 segnalazioni), la quota classificata come «lesione» varia dallo 0,6% al 44,2% a seconda del sistema. L'autore mostra che questa differenza dipende in buona parte da come vengono compilati i campi, e che in circa una segnalazione su sette etichetta e codici sul paziente vanno in direzioni diverse.", "Nota sul limite: sono segnalazioni spontanee, senza il numero di interventi eseguiti; non permettono di giudicare né di confrontare la sicurezza dei diversi sistemi."], "paz": ["Chirurgia robotica del ginocchio: cosa significano le segnalazioni raccolte negli archivi pubblici", "Negli Stati Uniti chiunque può segnalare un problema legato a un dispositivo medico, e le segnalazioni finiscono in un archivio pubblico. Uno studio le ha analizzate per quattro sistemi robotici usati per le protesi e ha trovato che il modo di classificarle varia molto da un sistema all'altro.", "Nota rassicurante: l'autore sottolinea che queste segnalazioni non indicano quanto sia sicuro un sistema e non servono a metterli a confronto."], "kw": "protesi di ginocchio, chirurgia robotica, sicurezza dei dispositivi, segnalazioni, protesi totale"}};

var ARTICLES=[{n:1,mono:'m-gray',dot:'green',sec:'res',j:'J ISAKOS',h:'Crociato: il presoaking dei trapianti in vancomicina ha evidenza solo osservazionale e diretta per gli ischiocrurali; per il quadricipite c\'è un segnale non confermato',v:'Revisione «State of the Art» (ricerca su PubMed aggiornata all\'11 ottobre 2026). Coorti comparative ampie e analisi aggregate associano il presoaking a meno artrite settica dopo LCA, con l\'evidenza più diretta per gli ischiocrurali; i pochi RCT sono sottodimensionati per un evento raro. Per quadricipite, rotuleo e allotrapianto l\'evidenza è limitata o indiretta, e una serie 2026 non controllata sul quadricipite segnala un possibile problema di sicurezza, non confermato.',ax:'Salim, Araújo, Vertullo, Pfeiffer, de Sa, Musahl',date:'nov 2026',meta:'revisione «State of the Art» (narrativa), solo abstract',pmid:'42998406',doi:'10.1016/j.jisako.2026.101237',journal:'Journal of ISAKOS : joint disorders & orthopaedic sports medicine',authors:'Salim R, Araújo PH, Vertullo CJ, Pfeiffer TR, de Sa D, Musahl V',design:'Revisione narrativa strutturata con ricerca su PubMed aggiornata all\'11 ottobre 2026, integrata da screening a ritroso delle citazioni e da linee guida e sintesi di evidenza mirate. Valuta razionale biologico, efficacia clinica, sicurezza, implementazione, evidenza per tipo di innesto, ipersensibilità, uso responsabile degli antibiotici, variazioni geografiche, costo-efficacia e controversie. Livello basso (revisione narrativa). Numero di studi inclusi, concentrazione e tempo di immersione, e dimensione dell\'effetto: non riportati nell\'abstract.',pop:'Non applicabile (revisione narrativa); ricostruzioni legamentose, soprattutto del LCA.',results:'Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract. In termini qualitativi: coorti comparative ampie e analisi aggregate associano il presoaking a tassi più bassi di artrite settica dopo LCA, con l\'evidenza più diretta per gli ischiocrurali; l\'evidenza randomizzata è limitata e sottodimensionata per un evento raro; il beneficio assoluto varia con il rischio infettivo di base; nessun danno dimostrato con i protocolli brevi più studiati.',concl:'Gli autori: il presoaking in vancomicina può essere considerato come aggiunta alla profilassi sistemica standard nel LCA con ischiocrurali, entro un protocollo standardizzato; non sostituisce le misure di prevenzione, e l\'estrapolazione ad altri innesti o ad altri contesti deve rispecchiare quanto è diretta l\'evidenza. Priorità future: protocollo per tipo di innesto, evidenza comparativa prospettica, sorveglianza della resistenza antimicrobica, esiti a lungo termine su innesto e cartilagine.',limits:'Revisione narrativa: la selezione degli studi non è riproducibile dall\'abstract e non c\'è alcun dato aggregato · Evidenza clinica prevalentemente osservazionale: associazione, non causa · RCT sottodimensionati per un evento raro come l\'artrite settica · Per quadricipite, rotuleo, allotrapianto e revisioni l\'evidenza è limitata o indiretta; la serie 2026 sul quadricipite è non controllata e, secondo gli stessi autori, non è una controindicazione ma un segnale non confermato · Dichiarazione di conflitto di interesse: non riportata nell\'abstract',perte:'Verde: tocca la sicurezza del tuo innesto. I dati diretti sul presoaking riguardano gli ischiocrurali, mentre per il quadricipite c\'è una sola serie non controllata che segnala un possibile problema di sicurezza, non confermato. Cosa fare: nessun cambio sulla base dell\'abstract; se il presoaking del quadricipite fa parte del tuo protocollo, apri il testo completo per leggere quella serie (che cosa ha osservato e con quale protocollo), perché l\'abstract non lo dice.'},
{n:2,mono:'m-gray',dot:'green',sec:'res',j:'BMC Musculoskelet Disord',h:'Crociato con iperlassità generalizzata: con il Lemaire modificato la differenza al KT-1000 cala da 11,77 a 1,68 mm, ma è una serie di 25 senza confronto',v:'Serie retrospettiva monocentrica (Tianjin; livello IV): 25 pazienti con rottura del LCA e iperlassità generalizzata, operati con LCA a singolo fascio con ischiocrurali più tenodesi laterale di Lemaire modificata, follow-up medio 25,76 ± 1,42 mesi. Differenza laterale al KT-1000 da 11,77 ± 1,80 a 1,68 ± 1,25 mm (p < 0,001); Lysholm da 55,48 ± 19,62 a 91,32 ± 4,89. Nessun gruppo di confronto: gli autori chiedono studi comparativi.',ax:'Ren, Qian, Xing, Meng, Wang, Huang, Cao',date:'nov 2026',meta:'serie retrospettiva, 25 pazienti, livello IV, solo abstract',pmid:'42995576',doi:'10.1186/s12891-026-10495-8',journal:'BMC musculoskeletal disorders',authors:'Ren F, Qian J, Xing Y, Meng B, Wang R, Huang J, Cao J',design:'Revisione retrospettiva di 25 pazienti con rottura del LCA e iperlassità generalizzata operati fra gennaio 2021 e ottobre 2023 con LCA a singolo fascio con tendini ischiocrurali autologhi e tenodesi extra-articolare laterale di Lemaire modificata. Stabilità valutata prima e al follow-up con Lachman, cassetto anteriore, pivot-shift e differenza laterale al KT-1000; esiti riferiti con Tegner, Lysholm, IKDC soggettivo e grading IKDC oggettivo. Livello IV, braccio singolo. Fissazione dell\'innesto e del LET, criterio di iperlassità generalizzata e sede di inserzione del LET: non riportati nell\'abstract.',pop:'25 pazienti con rottura del LCA e iperlassità generalizzata, tutti seguiti per un follow-up medio di 25,76 ± 1,42 mesi; nessuna complicanza maggiore registrata. Età e sesso: non riportati nell\'abstract.',results:'Differenza laterale al KT-1000 da 11,77 ± 1,80 a 1,68 ± 1,25 mm (p < 0,001). Lysholm da 55,48 ± 19,62 a 91,32 ± 4,89 e IKDC soggettivo da 48,04 ± 8,41 a 86,12 ± 4,03 (p < 0,001); Tegner finale 5,12 ± 1,13 contro 5,44 ± 1,29 prima dell\'infortunio (p = 0,382). Lassità residua di grado I: Lachman in 4 pazienti, cassetto anteriore in 10, pivot-shift in 5. Iperestensione passiva da +7,80° ± 6,60° a +6,30° ± 4,50° (p = 0,046); flessione da 127,00° ± 11,82° a 135,60° ± 2,63° (p = 0,001). Rotture dell\'innesto e ritorno allo sport: non riportati nell\'abstract.',concl:'Gli autori: in questa serie preliminare a braccio singolo, LCA con ischiocrurali più Lemaire modificata si associa a miglioramenti significativi della stabilità sagittale e rotatoria e dei punteggi funzionali a breve termine; servono studi comparativi per dire se superi la sola ricostruzione.',limits:'Serie retrospettiva a braccio singolo di 25 pazienti, livello IV: senza confronto con la sola ricostruzione non dice se il LET aggiunga qualcosa · Follow-up medio di circa due anni: la rottura dell\'innesto è un evento raro e tardivo, non valutabile · Innesto di ischiocrurali con Lemaire modificata: non è il tuo costrutto (quadricipite o retto femorale, LET onlay) · Il miglioramento è prima-dopo: guarigione e regressione verso la media non sono separabili · Lassità residua di grado I in una parte dei pazienti (pivot-shift in 5 su 25)',perte:'Verde: tocca la tensione sul LET, ma senza spostarla. L\'innesto è di ischiocrurali e manca il braccio di controllo, quindi non si può dire se il Lemaire aggiunga qualcosa alla sola ricostruzione nell\'iperlassità; i numeri di stabilità sono comunque coerenti con l\'idea che il LET controlli la rotazione. Cosa fare: nessun cambio; per un paziente con iperlassità generalizzata è una serie da citare come coerente, non probante.'},
{n:3,mono:'m-gray',dot:'green',sec:'res',j:'Ann Jt',h:'Menisco nel crociato dell\'atleta professionista: 5 studi e 519 pazienti, si preserva quando si può; nel mediale l\'all-inside fallisce di più',v:'Revisione sistematica PRISMA (Ochsner, New Orleans; livello medio per la rubrica, studi retrospettivi eterogenei) di 5 studi su 519 atleti professionisti operati di LCA, età media ponderata 23,7 anni, 18% donne. Lesioni meniscali nel 59-86%; la più comune è la longitudinale del corno posteriore, frequenti anche rampa e radice posteriore laterale. Si ripara la maggior parte delle lesioni riparabili; le mediali falliscono e finiscono in meniscectomia più delle laterali, soprattutto con tecnica all-inside.',ax:'Few, Mullen, Wilder, Godshaw',date:'ott 2026',meta:'revisione sistematica PRISMA, 5 studi, 519 pazienti, solo abstract (PMC ID presente, non letto)',pmid:'42999722',doi:'10.21037/aoj-2026-0017',journal:'Annals of joint',authors:'Few WE, Mullen M, Wilder JH, Godshaw B',design:'Revisione sistematica secondo PRISMA; ricerca su PubMed dall\'inizio a settembre 2025. Inclusi studi su atleti professionisti adulti (oltre 18 anni) operati di ricostruzione del LCA con gestione dettagliata delle lesioni meniscali concomitanti; estratti incidenza, morfologia, trattamento ed esiti. Qualità valutata con MINORS. Studi retrospettivi eterogenei. Punteggi MINORS, definizione di fallimento e tassi per tecnica: non riportati nell\'abstract.',pop:'519 pazienti in 5 studi (18% donne; età media ponderata 23,7 anni), atleti professionisti; 4 studi con follow-up minimo di 1 anno.',results:'Lesioni meniscali nel 59-86% dei pazienti nei diversi studi; la longitudinale del corno posteriore è la più frequente, con rampa e rottura della radice posteriore laterale spesso presenti. Preservazione favorita, con riparazione nella maggior parte delle lesioni riparabili. Le lesioni mediali mostrano più fallimenti e meniscectomie secondarie delle laterali, soprattutto con all-inside; inside-out e suture hook appaiono più favorevoli sul lato mediale. La riparazione non sembra compromettere il ritorno allo sport. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: i dati sostengono una strategia «preservazione prima» nell\'atleta ad alta richiesta; la meniscectomia va riservata al tessuto irreparabile o non funzionale; limiti: studi retrospettivi e variabilità dei protocolli riabilitativi.',limits:'Solo 5 studi retrospettivi eterogenei: associazione, non causa; la scelta di riparare dipende dalla lesione e dal chirurgo (confondimento da indicazione) · Atleti professionisti, età media 23,7 anni e 18% donne: non è il tuo paziente medio · «Più fallimenti» e «più favorevole» non sono quantificati nell\'abstract · Ricerca ferma a settembre 2025 · «Non compromette il ritorno allo sport» senza intervalli di confidenza nell\'abstract',perte:'Verde: tocca menisco, rampa e radice. Va nella direzione che già segui (preservare, riparare la radice); il dato pratico è che nel mediale l\'all-inside fallisce più dell\'inside-out e delle suture hook, ma l\'abstract non dà i numeri. Cosa fare: nessun cambio; se usi l\'all-inside su lesioni mediali o a rampa, apri il testo completo su PMC per i tassi per tecnica.'},
{n:4,mono:'m-gray',dot:'green',sec:'res',j:'Ann Jt',h:'Osteotomie che riducono lo slope dopo fallimento del crociato: esiti incoraggianti con tre approcci anteriori, ma nessun RCT e tecniche da standardizzare',v:'Revisione narrativa (Duke e altri; livello basso) sulle osteotomie che riducono lo slope tibiale posteriore nel LCA deficiente o nella ricostruzione fallita. Quattro approcci principali; le osteotomie anteriori sovra-, infra- e trans-tuberositarie mostrano esiti incoraggianti nei fallimenti dell\'innesto con slope elevato, ma l\'evidenza è fatta di studi retrospettivi e report tecnici e non esiste alcun RCT comparativo. Proposto un algoritmo di indicazioni.',ax:'Williams, Olomi, Yang, Goel, Kennedy, Ryu, Lau',date:'ott 2026',meta:'revisione narrativa, solo abstract (PMC ID presente, non letto)',pmid:'42999539',doi:'10.21037/aoj-2026-0038',journal:'Annals of joint',authors:'Williams HA, Olomi S, Yang W, Goel S, Kennedy O, Ryu J, Lau BC',design:'Revisione narrativa della letteratura sulle osteotomie di riduzione dello slope per revisione del LCA e LCA deficiente, con studi chiave su tecniche, indicazioni ed esiti; evidenza basata soprattutto su studi retrospettivi e relazioni tecniche. Gli autori propongono un algoritmo di trattamento in base alle indicazioni. Livello basso. Strategia di ricerca, numero di studi e soglia di slope: non riportati nell\'abstract.',pop:'Non applicabile (revisione narrativa); LCA deficiente o ricostruzione fallita con slope tibiale posteriore elevato.',results:'Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: le osteotomie riduttive dello slope mostrano esiti promettenti dopo il fallimento della ricostruzione, ma l\'eterogeneità di metodi ed esiti impedisce conclusioni definitive. La scelta dell\'approccio dipende da anatomia, quadro clinico ed esperienza del chirurgo; servono pianificazione preoperatoria standardizzata, comprese le misure dello slope, ed esiti a lungo termine per ciascuna tecnica.',limits:'Revisione narrativa: selezione degli studi non riproducibile e nessun dato aggregato · Evidenza retrospettiva e tecnica, nessun RCT comparativo · Le guide paziente-specifiche in questa popolazione sono, per gli autori, insufficientemente documentate · La misura dello slope non è standardizzata, quindi le soglie non sono confrontabili fra studi · L\'algoritmo proposto è un\'opinione degli autori, non validato nell\'abstract',perte:'Verde: tocca osteotomia e slope, un tuo filone. Non porta numeri né un confronto fra tecniche: è una mappa delle indicazioni, utile come promemoria quando un crociato fallisce con slope alto. Cosa fare: nessun cambio; per un caso concreto serve il testo completo (su PMC) per l\'algoritmo e le soglie, che l\'abstract non riporta.'},
{n:5,mono:'m-gray',dot:'green',sec:'res',j:'J Robot Surg',h:'Robot in artroplastica: in 12.175 segnalazioni MAUDE etichetta di danno e codici del paziente spesso non coincidono; non vanno usati per classificare le piattaforme',v:'Analisi trasversale (Università di Tabuk; autore unico; livello basso) di 12.175 segnalazioni MAUDE della FDA su Mako, NAVIO/CORI, VELYS e ROSA (fino al 30 settembre 2026). Etichetta «lesione» nel 17,3%, dallo 0,6% (VELYS) al 44,2% (ROSA); in 1.785 segnalazioni (14,7%; IC 95% 14,0-15,3) etichetta e codici del paziente vanno in direzioni opposte. L\'autore avverte che non misura né sicurezza né danno.',ax:'Abushal',date:'nov 2026',meta:'analisi trasversale di segnalazioni MAUDE, 12.175 report, livello basso, solo abstract',pmid:'42995343',doi:'10.1007/s11701-026-04162-2',journal:'Journal of robotic surgery',authors:'Abushal MH',design:'Analisi trasversale del database MAUDE (accesso tramite openFDA, codice prodotto OLO, segnalazioni ricevute fino al 30 settembre 2026) per Mako e NAVIO/CORI (campo produttore) e VELYS e ROSA Knee/Recon (campo marca). Esito primario: co-occorrenza di un\'etichetta «lesione» con un codice «nessuna conseguenza», o di un\'etichetta non-lesione con un codice di danno; analisi di sensibilità con definizioni armonizzate e controllo dei duplicati. Le procedure non sono state confermate. Dati di sorveglianza passiva. Numero di segnalazioni per piattaforma e denominatori di interventi: non riportati nell\'abstract.',pop:'12.175 segnalazioni (non pazienti) su Mako, NAVIO/CORI, VELYS e ROSA; procedure non confermate.',results:'Su 12.175 segnalazioni, 2.106 (17,3%) hanno l\'etichetta «lesione», dallo 0,6% (VELYS) al 44,2% (ROSA). Un codice «nessuna conseguenza» compare nel 46,0% delle segnalazioni con etichetta lesione per Mako, nel 71,3% per NAVIO/CORI e nel 59,5% per ROSA; un codice di danno compare nel 12,8% delle segnalazioni VELYS con etichetta non-lesione. Co-occorrenza complessiva in 1.785 segnalazioni (14,7%; IC 95% 14,0-15,3). Le direzioni restano con codici clinici, definizioni armonizzate e rimozione dei duplicati.',concl:'L\'autore: etichette e codici del paziente servono a scopi diversi e coesistono in direzioni diverse a seconda della piattaforma; questo riflette la natura dei campi, non un disaccordo di codifica dimostrato, né un danno al paziente, né la sicurezza del dispositivo. Le quote di danno ricavate da un solo campo non vanno usate per ordinare le piattaforme.',limits:'Segnalazioni spontanee: sottosegnalazione, nessun denominatore di interventi, procedure non confermate · Le percentuali per piattaforma dipendono da come ogni produttore compila i campi: 0,6% contro 44,2% non è un confronto di sicurezza (lo dice l\'autore) · Autore unico, un solo database; l\'abstract non dà i numeri assoluti per il VELYS · Non riguarda esiti clinici né rischio di revisione',perte:'Verde: tocca il VELYS, come regola di lettura e non come dato di sicurezza. La quota più bassa di «lesione» del VELYS (0,6%) non prova che sia più sicuro: dipende da come si compilano le segnalazioni, e l\'abstract lo esclude. Cosa fare: nessun cambio; se un paziente o un collega cita queste percentuali, sono un dato di sorveglianza passiva non confrontabile fra piattaforme.'}];

var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];

var BRIEF_TEXT="Lunedì nove novembre, cinque lavori, nessuna scheda rossa. Nessun richiamo di dispositivi nuovo che ti riguardi, nessuna ritrattazione di lavori che abbiamo citato e nessun citante nuovo sui tuoi verdetti passati; il raccoglitore è quello di ieri mattina e tutte le fonti hanno risposto. Il lavoro del giorno è una revisione sul presoaking dei trapianti in vancomicina nella ricostruzione del crociato, firmata fra gli altri da Musahl. L'artrite settica dopo il crociato è rara ma seria, e gli studi osservazionali la associano a meno infezioni quando il trapianto viene immerso nell'antibiotico. Ma l'evidenza più diretta riguarda gli ischiocrurali, i pochi studi randomizzati sono troppo piccoli per un evento raro, e per il quadricipite c'è una sola serie non controllata del duemilaventisei che segnala un possibile problema di sicurezza, non confermato. Per il tuo innesto è la parte che conta: nessun cambio sulla base dell'abstract, ma vale aprire il testo completo. Seconda scheda, una serie di venticinque pazienti con iperlassità generalizzata operati con ischiocrurali e Lemaire modificato: la lassità misurata al KT-1000 cala molto e i punteggi salgono, ma non c'è un gruppo di controllo, l'innesto non è il tuo e il follow-up è di circa due anni. Terza, una revisione sistematica sul menisco nel crociato dell'atleta professionista, cinque studi e cinquecentodiciannove pazienti: si preserva quando si può, e nel mediale l'all-inside sembra fallire più dell'inside-out, ma l'abstract non dà i numeri. Quarta, le osteotomie che riducono lo slope dopo il fallimento del crociato: esiti incoraggianti per tre approcci anteriori, nessuno studio randomizzato. Quinta, un'analisi delle segnalazioni americane MAUDE sui robot per le protesi, dodicimilacentosettantacinque segnalazioni: etichette di danno e codici del paziente si contraddicono in circa una su sette, quattordici virgola sette per cento, intervallo da quattordici a quindici virgola tre, e l'autore esclude che servano a classificare la sicurezza dei sistemi, VELYS compreso. Nessuna tensione si sposta oggi.";

var BRIEF_DIALOGO=[{"chi": "A", "t": "Lunedì nove novembre, cinque lavori, nessuna scheda rossa. Nessun richiamo nuovo che ti riguardi, nessuna ritrattazione e nessun citante nuovo sui tuoi verdetti passati."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Una revisione sul bagno dei trapianti in vancomicina nel crociato, firmata fra gli altri da Musahl. Gli studi osservazionali lo associano a meno artriti settiche, ma i dati più diretti sono per gli ischiocrurali."}, {"chi": "B", "t": "E per il quadricipite?"}, {"chi": "A", "t": "C'è una sola serie del duemilaventisei, non controllata, che segnala un possibile problema di sicurezza, non confermato. Gli studi randomizzati sono troppo piccoli per un evento così raro."}, {"chi": "B", "t": "Quindi per me?"}, {"chi": "A", "t": "Nessun cambio sull'abstract; se il presoaking del quadricipite fa parte del tuo protocollo, vale aprire il testo completo per leggere quella serie."}, {"chi": "B", "t": "Le altre schede?"}, {"chi": "A", "t": "Una serie di venticinque pazienti con iperlassità operati con ischiocrurali e Lemaire modificato: la lassità cala, ma senza gruppo di controllo e con un innesto che non è il tuo."}, {"chi": "B", "t": "E il menisco?"}, {"chi": "A", "t": "Revisione sistematica su atleti professionisti, cinque studi: si preserva quando si può, e nel mediale l'all-inside sembra fallire di più, ma l'abstract non dà i numeri."}, {"chi": "B", "t": "Slope e robot?"}, {"chi": "A", "t": "Le osteotomie che riducono lo slope dopo il fallimento del crociato hanno esiti incoraggianti, senza studi randomizzati. E sulle segnalazioni americane dei robot per protesi l'autore stesso dice che non servono a classificare la sicurezza dei sistemi, VELYS compreso."}, {"chi": "B", "t": "Quindi nessuna tensione si sposta oggi."}, {"chi": "A", "t": "Esatto: giornata di conferme e di cautele."}];

var CONF={"1": "bassa", "2": "bassa", "3": "media", "4": "bassa", "5": "bassa"};

var BUILD_DATE="2026-11-09";

var PICK=1;

